<?php require 'config/database.php';$pageTitle='Jobs';$rows=$conn->query('SELECT j.*,c.category_name FROM jobs j JOIN categories c ON c.category_id=j.category_id ORDER BY j.job_id DESC');include 'includes/header.php';?>
